parameters.inputSchema:
{
  "type": "object",
  "required": [
    "pipeline_bottleneck",
    "detected_problem",
    "evidence_quote",
    "recommended_offer",
    "problem_alignment_score",
    "evidence_type",
    "all_opportunities",
    "owner_name",
    "owner_name_confidence"
  ],
  "properties": {
    "pipeline_bottleneck": {
      "type": "string",
      "description": "Two or three sentences answering: if 500 new customers contacted this business tomorrow, which step breaks first and what does that cost them. Write it so a salesperson could read it aloud on a call. Empty string only if the business shows no bottleneck at all."
    },
    "detected_problem": {
      "type": "string",
      "description": "The single highest-value fixable problem, stated specifically. Empty string if none found."
    },
    "evidence_quote": {
      "type": "string",
      "description": "An exact quote from a review or the website, or a plainly stated structural observation. Never fabricated. Empty string if none found."
    },
    "recommended_offer": {
      "type": "string",
      "description": "Exactly one offer from the menu that clears the primary problem. Empty string if no problem found."
    },
    "problem_alignment_score": {
      "type": "number",
      "description": "0 to 5. How well the evidence supports the primary recommendation. 5 is counted or directly visible proof, 3 is a reasonable inference, 0 is nothing found."
    },
    "evidence_type": {
      "type": "string",
      "description": "Exactly one of: Proven, Likely. Use Proven only when the evidence is counted or directly visible. Empty string if no problem found."
    },
    "all_opportunities": {
      "type": "string",
      "description": "EVERY automation opportunity you can find, not only the primary one, one per line. Format each line exactly as: OFFER NAME | Proven or Likely | the specific evidence in one short sentence. List them strongest first. Most businesses have two or three. Empty string only if there are genuinely none."
    },
    "owner_name": {
      "type": "string",
      "description": "Owner or founder name, only if visibly signed on a review reply or stated on an About or Team page. Never guessed. Empty string if not found."
    },
    "owner_name_confidence": {
      "type": "number",
      "description": "0 to 1 confidence that owner_name is correct. 0 if owner_name is empty."
    }
  }
}

