parameters.jsCode:
// Deterministic footprint checks. No AI guessing - these are countable facts
// read off the site's own links and copy, so they are identical every run.
const web = $('Consolidate Website Text').first().json;
const yt  = $('Normalize YouTube Data').first().json;

let lastUpload = '';
try {
  const up = $('Get Latest Upload').first().json;
  if (up && up.items && up.items[0] && up.items[0].snippet) {
    lastUpload = String(up.items[0].snippet.publishedAt || '').substring(0, 10);
  }
} catch (e) { lastUpload = ''; }

const rawLinks = web.website_links || '';
const text  = (web.website_text  || '').toLowerCase();
const links = rawLinks.toLowerCase();
const all   = text + '\n' + links;

// ---- booking ----
// Vendor lists are grouped by vertical so this is not dental-only. Add the
// booking software for any new vertical here before running a batch on it -
// an unrecognised vendor silently becomes 'Has booking page, unconfirmed'.
//
// UK PROPERTY + UK AESTHETICS added 19 Aug 2026 - the operator's primary
// target verticals. UK SPELLING MATTERS: British sites say 'enquiry', never
// 'inquiry', and the US-only patterns missed them completely.
const schedulers = [
  // UK estate agency / lettings - CRM, viewing booking, tenancy tooling
  'reapit','alto.zoopla','jupix','dezrez','street.co.uk','acquaint','rexsoftware','vebra',
  'expertagent','agentos','gnomen','apex27','letmc','openview','propertyhive','yourkeys',
  'viewber','goodlord','fixflo','canopy.rent','homeflow','starberry',
  // UK aesthetics / med spa / private clinic
  'pabau','phorest','treatwell','gettimely','cliniko','clinicsoftware','semble','heydoc',
  'writeupp','clinicminds','janeapp','zenoti','ovatu','kitomba','shortcuts','consentz',
  'clinicea','facesconsent','aestheticnursesoftware','mangomint','blvd.co',
  // UK dental
  'dentally','softwareofexcellence','carestream','r4dental','zesty.co.uk','dentr',
  'systemsfordentists',
  // UK trades / home improvement
  'payaca','powerednow','tradify','commusoft','simprogroup','klipboard','okappy',
  'yourtradebase','bigchange','joblogic',
  // dental / medical (US-origin, still turn up on UK sites)
  'appointnow','patientconnect','zocdoc','nexhealth','denticon','modento','localmed','dentrix',
  'yapi','revenuewell','patientpop','sesame','doctible','carestack','nextpatient','luma health',
  // home services / trades - HVAC, plumbing, electrical, roofing, cleaning
  'servicetitan','housecallpro','getjobber','jobber.com','workiz','fieldedge','servicem8',
  'jobnimbus','servicefusion','thumbtack.com/book','setmore',
  // salon / spa / wellness
  'mindbody','vagaro','booksy','schedulicity','fresha','glossgenius','squareup.com/appointments',
  // generic, any vertical
  'flexbooker','calendly','acuityscheduling','simplybook','youcanbook.me','cal.com','tidycal',
  'chilipiper','hubspot.com/meetings','koalendar','savvycal','10to8','bookwhen','appointedd',
  'bookinglive','reservio'
];
const hasScheduler  = schedulers.some(s => all.includes(s));
const hasBookingPath = ['/book','/booking','/appointment','/schedul','/reserve','/estimate','/quote',
  '/viewing','/valuation','/appraisal','/enquiry','/enquire','/consultation'].some(p => links.includes(p));

// A recognised vendor name does NOT prove real self-service booking. Several
// of these are routinely deployed as a request form the business answers by
// hand - CITIDental runs PatientConnect365 at a /RequestAppointment/ URL.
// Verified 16 Aug 2026 against the live sites: when the link itself says
// 'request', that beats the vendor name, so requestish is tested FIRST.
// Tradeoff accepted: a business running real booking AND a separate request
// form somewhere reads as 'Form, answered by hand'. Under-claiming is the safe
// direction - it never puts a false 'they already have booking' on a call.
//
// DELIBERATE for UK property: only 'request / arrange / enquire' wording lands
// here. Plain 'book-a-viewing' and 'book-a-valuation' are left to the booking
// path check instead. If every estate agent were forced to 'Form, answered by
// hand' the field would stop discriminating between agents who have automated
// and agents who have not - which is the entire point of measuring it.
const requestPatterns = ['request-an-appointment','appointment-request','request-appointment','requestappointment','request-a-','request-consultation','appointment-inquiry','appointment-enquiry','request-info','free-estimate','request-quote','get-a-quote',
  'request-a-viewing','viewing-request','arrange-a-viewing','arrange-viewing',
  'request-a-valuation','valuation-request','free-valuation','book-a-callback',
  'request-a-callback','callback-request','enquiry-form','make-an-enquiry','consultation-request'];
const requestish = requestPatterns.some(p => links.includes(p))
  || text.includes('request an appointment') || text.includes('request a consultation')
  || text.includes('request a quote') || text.includes('free estimate')
  || text.includes('request a viewing') || text.includes('arrange a viewing')
  || text.includes('request a valuation') || text.includes('arrange a valuation')
  || text.includes('book a free valuation') || text.includes('make an enquiry')
  || text.includes('submit an enquiry') || text.includes('request a callback')
  || text.includes('will get in touch') || text.includes('we will contact you')
  || text.includes('we will be in touch') || text.includes('a member of our team');
const hasTel = links.includes('tel:');

let bookingType = 'No way to book online';
if (requestish) bookingType = 'Form, answered by hand';
else if (hasScheduler) bookingType = 'Books online instantly';
else if (hasBookingPath) bookingType = 'Has booking page, unconfirmed';
else if (hasTel) bookingType = 'Phone only';

// ---- paperwork, capture, chat ----
// UK additions: tenancy and referencing paperwork for lettings agents, consent
// and medical-history forms for aesthetics clinics. The old list was
// patient/medical wording only, which is why it read blank outside dentistry.
const hasForms        = ['patient-form','patient_form','patientforms','new-patient','newpatient','/forms','#forms','-forms','forms.html','online-forms','intake','registration','.pdf',
  'tenancy-application','application-form','landlord-form','referencing','right-to-rent',
  'tenancy-agreement','memorandum-of-sale','consent-form','medical-history','consultation-form','.docx'].some(h => all.includes(h));
// An 'instant valuation' widget gates its result behind an email address -
// that IS lead capture, so an agent already running one must not be pitched
// email capture as if it were missing.
const hasEmailCapture = ['newsletter','subscribe','mailchimp','constantcontact','klaviyo','join our list','email list',
  'property alerts','property-alerts','register for alerts','instant alerts','register with us',
  'dotdigital','campaign monitor','sendinblue','brevo','mailerlite','activecampaign',
  'instant-valuation','instant valuation','value my property'].some(h => all.includes(h));
const hasLeadMagnet   = ['free report','free guide','free ebook','free e-book','download our','free download','whitepaper','free checklist','free consultation guide','-report/','-report.','/report/','free-guide','/guide/',
  'landlord guide','sellers guide','seller-guide','buyers guide','buyer-guide','moving guide',
  'free brochure','price guide','price list','treatment guide','tenant-guide'].some(h => all.includes(h));
const hasLiveChat     = ['tawk.to','intercom','drift.com','livechat','podium','birdeye','olark','zendesk','chatwidget','live chat',
  'yomdel','tidio','crisp.chat','smartsupp','chatra','freshchat','helpcrunch','userlike','jivochat'].some(h => all.includes(h));

// WhatsApp enquiries: a wa.me link means a human is answering messages by hand
// on somebody's phone. That is the exact job the AI receptionist / WhatsApp bot
// offer replaces, so it is a buying signal - never a reason to skip them.
const hasWhatsApp = ['wa.me/','whatsapp.com/send','api.whatsapp.com','web.whatsapp.com','whatsapp'].some(h => all.includes(h));

// Outsourced call answering or managed live chat. If they already pay Moneypenny
// or Yomdel they have ALREADY admitted the pain AND already hold budget for it -
// the strongest qualifying signal on the whole page. Never read this as 'solved'.
const answeringServices = ['yomdel','moneypenny','alldayppc','answer4u','face-for-business',
  'verbalink','callcare','ansaback','officeanswers','bemyreceptionist','virtual receptionist',
  'answering service','call answering'];
const usesAnsweringService = answeringServices.some(s => all.includes(s));

// ---- locations: distinct phone numbers is the most reliable outside proxy ----
// slice(-10) normalises UK numbers correctly: 020 7123 4567, 02071234567 and
// +442071234567 all reduce to the same 2071234567.
const telMatches = rawLinks.match(/tel:[+0-9()\-\s.]+/gi) || [];
const distinctTels = Array.from(new Set(telMatches.map(t => t.replace(/[^0-9]/g, '').slice(-10)).filter(Boolean)));
const locationCount = distinctTels.length || 1;

// ---- years established ----
// Read off the FULL page markdown upstream, not the 6000-char excerpt.
// Truncating first hid "Boston's Dental Office Since 1998" and zeroed this field.
let yearsEstablished = 0;
const foundedYear = Number(web.founded_year || 0);
const nowYear = new Date().getFullYear();
if (foundedYear >= 1900 && foundedYear <= nowYear) yearsEstablished = nowYear - foundedYear;

// ---- emails they publish on their own site ----
// Free: the scrape is already paid for and mailto links sit right in it.
// Deliberately NOT passed to the AI - it serves no analytical purpose there.
const siteHost = String(($('Normalize Reviews').first().json.website) || '')
  .replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].toLowerCase();
const emailJunk = ['example.com','yourdomain','domain.com','sentry','wixpress','godaddy','.png','.jpg','.jpeg','.gif','.svg','.webp','@2x','no-reply','noreply','donotreply'];
const rawEmails = (all.match(/[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}/gi) || []).map(e => e.toLowerCase());
const foundEmails = Array.from(new Set(rawEmails)).filter(e => !emailJunk.some(j => e.includes(j)));
// An address on their own domain beats a stray third-party one every time.
const sameDomain = siteHost ? foundEmails.filter(e => e.endsWith('@' + siteHost)) : [];
const bestEmail = sameDomain[0] || foundEmails[0] || '';

// Roughly half of local businesses publish no address at all - the contact
// form IS the anti-scraping measure. Verified 16 Aug 2026: 3 of 5 in this
// batch genuinely have none anywhere on their site. So when nothing is found,
// generate the standard candidates off their own domain.
// These are GUESSES. They are deliberately kept OUT of best_email so
// Workflow 3 never drafts to an unverified address - a bounce damages sender
// reputation, which is slow and expensive to rebuild. Verify before sending.
// 'enquiries@' and 'lettings@' are the common UK forms and are listed first.
let emailGuesses = '';
if (!bestEmail && siteHost) {
  emailGuesses = ['info','enquiries','office','contact','hello','lettings','sales','admin']
    .map(function(p){ return p + '@' + siteHost; }).join('\n');
}

// ---- youtube verdict ----
// NOTE: aesthetics clinics and salons are Instagram-first, not YouTube-first.
// A 'No channel found' verdict for those verticals is weak evidence, not proof
// of a content gap. Treat it accordingly until an Instagram signal is built.
const subs = Number(yt.youtube_subscribers || 0);
const views = Number(yt.youtube_views || 0);
const vids = Number(yt.youtube_video_count || 0);
const avg  = Number(yt.youtube_avg_views || 0);

let dormantYears = 0;
if (lastUpload) {
  const d = new Date(lastUpload);
  if (!isNaN(d.getTime())) dormantYears = (Date.now() - d.getTime()) / (1000 * 60 * 60 * 24 * 365);
}

let ytVerdict = 'No channel found';
if (!yt.youtube_channel_url) ytVerdict = 'No channel found';
else if (lastUpload && dormantYears >= 1.5) ytVerdict = 'Abandoned';
else if (vids > 0 && subs > 0 && (views / subs) > 2000 && avg > 500) ytVerdict = 'Buying views, no real audience';
else if (vids > 0 && vids < 5) ytVerdict = 'Barely used';
else if (vids > 0 && avg < 200) ytVerdict = 'Few views per video';
else if (vids > 0) ytVerdict = 'Active';

const yn = b => b ? 'YES' : 'NO';
const footprintSummary = [
  'Booking on the site: ' + bookingType,
  'Downloadable or printable client forms: ' + yn(hasForms),
  'Email capture or newsletter: ' + yn(hasEmailCapture),
  'Lead magnet such as a free report or guide: ' + yn(hasLeadMagnet),
  'Live chat widget: ' + yn(hasLiveChat),
  'Takes enquiries on WhatsApp, answered by hand: ' + yn(hasWhatsApp),
  'Pays an outsourced answering service or managed live chat: ' + yn(usesAnsweringService) + (usesAnsweringService ? ' - they already pay humans to cover this, so both budget and pain are proven. Treat as a strong opportunity, NOT as already solved.' : ''),
  'Distinct phone numbers on the site (proxy for number of locations): ' + locationCount,
  'Years established: ' + (yearsEstablished ? yearsEstablished + ' years' : 'not stated on the site'),
  'YouTube: ' + ytVerdict + ' - ' + subs + ' subscribers, ' + views + ' total views, ' + vids + ' videos, ' + avg + ' average views per video' + (lastUpload ? ', last upload ' + lastUpload : ', last upload date unknown')
].join('\n');

return [{ json: {
  booking_type: bookingType,
  has_downloadable_forms: hasForms,
  has_email_capture: hasEmailCapture,
  has_lead_magnet: hasLeadMagnet,
  has_live_chat: hasLiveChat,
  has_whatsapp: hasWhatsApp,
  uses_answering_service: usesAnsweringService,
  location_count: locationCount,
  years_established: yearsEstablished,
  youtube_verdict: ytVerdict,
  youtube_last_upload: lastUpload,
  youtube_avg_views: avg,
  found_emails: foundEmails.join('\n'),
  email_guesses: emailGuesses,
  best_email: bestEmail,
  footprint_summary: footprintSummary
}}];

// The Contact/Booking/Forms page is now chosen upstream in
// 'Normalize Website Text', where the FULL link array is still available.
// It used to be picked here from an already-truncated 2500-char string,
// so any contact link past ~45 links was invisible - which is exactly why
// email discovery kept finding nothing. This node now just passes it along.
return [{ json: {
  website_text: $json.website_text,
  website_links: $json.website_links,
  founded_year: $json.founded_year,
  secondary_url: $json.secondary_url || ''
}}];

// Always read the homepage text/links by name so this works whether or
// not a secondary page was scraped - the true branch overwrote $json with
// the Firecrawl response (HTTP nodes replace $json), the false branch didn't.
const home = $('Normalize Website Text').first().json;
let text = home.website_text || '';
let links = home.website_links || '';

if ($json.data && $json.data.markdown) {
  const secondaryUrl = $('Find Secondary Page to Scrape').first().json.secondary_url || '';
  const secondaryText = String($json.data.markdown).substring(0, 3000);
  text = (text + '\n\n--- SECONDARY PAGE (' + secondaryUrl + ') ---\n\n' + secondaryText).substring(0, 7000);

  if (Array.isArray($json.data.links)) {
    const existing = links ? links.split('\n') : [];
    links = Array.from(new Set([...existing, ...$json.data.links])).slice(0, 260).join('\n').substring(0, 3200);
  }
}

return [{ json: { website_text: text, website_links: links, founded_year: home.founded_year } }];

// Code node: no native n8n node can chunk a list into API-sized batches.
// DataForSEO accepts up to 100 review jobs in ONE post. We group every lead
// here and post them all up front, instead of one job per lead inside the loop.
// priority: 2 = DataForSEO high-priority queue. Normal priority was still
// 'Task In Queue' after 135s on run 192, leaving 7 of 10 leads with no reviews.
const CHUNK = 100;
const records = $input.all();
const out = [];

for (let i = 0; i < records.length; i += CHUNK) {
  const payload = records.slice(i, i + CHUNK)
    .map(r => ({
      place_id: r.json.fields['Place ID'],
      location_name: r.json.fields['City'],
      language_code: 'en',
      depth: 50,
      sort_by: 'newest',
      priority: 2,
      tag: r.json.id
    }))
    .filter(t => t.place_id);

  if (payload.length) {
    out.push({ json: { batch_index: out.length, task_count: payload.length, payload } });
  }
}

return out;

// Code node: flattening a nested API response into one item per job
// has no native equivalent.
const out = [];
for (const item of $input.all()) {
  const tasks = (item.json && item.json.tasks) || [];
  for (const t of tasks) {
    const recordId = (t.data && t.data.tag) || '';
    if (t.id && recordId) {
      out.push({ json: { task_id: t.id, record_id: recordId } });
    }
  }
}
return out;

// Code node: matching two lists together and computing review statistics
// is not something a native n8n node does in one step.
// Produces exactly one item per lead, reviews already attached, so the loop
// below never has to touch the network for reviews again.

const idToRecord = {};
for (const item of $('List Review Task IDs').all()) {
  idToRecord[item.json.task_id] = item.json.record_id;
}

const reviewsByRecord = {};
for (const item of $input.all()) {
  const t = item.json && item.json.tasks && item.json.tasks[0];
  if (!t) continue;
  const recId = (t.data && t.data.tag) || idToRecord[t.id];
  if (!recId) continue;
  const items = (t.result && t.result[0] && t.result[0].items) || [];
  if (!reviewsByRecord[recId] || items.length > reviewsByRecord[recId].length) {
    reviewsByRecord[recId] = items;
  }
}

const clean = (s) => String(s || '').replace(/\n/g, ' ').trim();

return $('Limit Leads This Run').all().map(rec => {
  const f = rec.json.fields || {};
  const reviews = reviewsByRecord[rec.json.id] || [];
  const negatives = reviews.filter(r => r.rating && typeof r.rating.value === 'number' && r.rating.value <= 3);
  const replied = reviews.filter(r => r.owner_answer).length;

  return {
    json: {
      record_id: rec.json.id,
      business_name: f['Business Name'] || '',
      website: f['Website'] || '',
      city: f['City'] || '',
      category: f['Category'] || '',
      place_id: f['Place ID'] || '',
      rating: Number(f['Rating'] || 0),
      review_count: Number(f['Review Count'] || 0),
      reviews_text: reviews.map(r => '- ' + clean(r.review_text) + (r.timestamp ? ' [' + r.timestamp + ']' : '')).join('\n').substring(0, 3000) || 'NOT FOUND',
      negative_reviews_text: negatives.map(r => '- [' + r.rating.value + '/5]' + (r.owner_answer ? ' [OWNER REPLIED]' : ' [NO OWNER REPLY]') + ' ' + (clean(r.review_text) || '(star rating only, reviewer wrote no text)') + (r.timestamp ? ' (' + String(r.timestamp).substring(0, 10) + ')' : '')).join('\n').substring(0, 4000) || 'NO NEGATIVE REVIEWS IN THIS BATCH',
      negative_review_count: negatives.length,
      unanswered_negative_count: negatives.filter(r => !r.owner_answer).length,
      owner_reply_rate: Math.round(replied * 100 / (reviews.length || 1)),
      reviews_fetched_count: reviews.length
    }
  };
});
